const NOTES={"1": [{"n": 1, "k": "Muka depan", "t": "Rahsia TurtleTrader untuk Trader FCPO", "h": "<p>Intisari penuh buku <i>The Complete TurtleTrader</i> (Michael W. Covel) — 14 bab, peraturan dagangan Turtle, dan cara mengaplikasikannya pada niaga hadapan minyak sawit mentah Bursa Malaysia.</p> 📘 14 bab dirumuskan📐 Peraturan + kiraan FCPO🗓️ Pelan tindakan 90 hari"}, {"n": 2, "k": "Peta Seminar", "t": "Apa yang kita akan belajar hari ini", "h": "<div class=\"nc\"><p class=\"nn\">1</p><h3>Kisah &amp; Eksperimen</h3><p>Bab 1–3: Richard Dennis, pertaruhan “bakat vs boleh diajar”, cara Turtle dipilih.</p></div><div class=\"nc\"><p class=\"nn\">2</p><h3>Falsafah Turtle</h3><p>Bab 4: kaedah saintifik, ikut trend, emosi, exit lebih penting dari entry.</p></div><div class=\"nc nc-amber\"><p class=\"nn\">3</p><h3>Peraturan Dagangan</h3><p>Bab 5: edge, breakout, N, saiz posisi, stop 2N, piramid, drawdown.</p></div><div class=\"nc\"><p class=\"nn\">4</p><h3>Realiti &amp; Kejatuhan</h3><p>Bab 6–10: hidup dalam pejabat Turtle, pilih kasih, Dennis tumbang &amp; bangkit.</p></div><div class=\"nc\"><p class=\"nn\">5</p><h3>Siapa Berjaya, Kenapa</h3><p>Bab 11–14: Jerry Parker, Curtis Faith, Salem Abraham, ketahanan mental.</p></div><div class=\"nc nc-dark\"><p class=\"nn\">6</p><h3>Aplikasi FCPO + Tindakan</h3><p>Spesifikasi kontrak, contoh kiraan, rutin harian, pelan 90 hari, kuiz.</p></div>"}, {"n": 3, "k": "Idea Besar Buku Ini", "t": "Boleh tak trading diajar kepada orang biasa?", "h": "<p>Pada 1983, Richard Dennis — trader legenda Chicago — merekrut orang biasa tanpa pengalaman, melatih mereka <b>dua minggu</b>, kemudian beri mereka dana sebenar untuk didagangkan.</p><p>Hasilnya: kumpulan “Turtle” ini mengaut <b>lebih USD 100 juta</b> keuntungan, dan beberapa orang kemudiannya menguruskan dana bernilai berbilion dolar.</p><div class=\"nc\"><p class=\"nn\">2</p><p>minggu latihan sahaja</p></div><div class=\"nc\"><p class=\"nn\">$100J+</p><p>keuntungan kolektif Turtle</p></div><div class=\"nc nc-amber\"><p><b>Pengajaran untuk kita:</b> kejayaan datang dari <b>peraturan yang jelas + disiplin</b>, bukan bakat semula jadi atau ijazah hebat.</p></div>"}, {"n": 4, "k": "Bahagian 1 · Bab 1–3", "t": "Kisah Dennis & Eksperimen Turtle", "h": "<p>Dari mana datangnya idea “trader boleh dilatih”, dan siapa yang dipilih.</p>"}, {"n": 5, "k": "Bab 1 · Nurture vs Nature", "t": "Pertaruhan dua sahabat: Dennis lawan Eckhardt", "h": "<div class=\"nc nc-dark\"><h3>Richard Dennis</h3><p>“Trading <b>boleh diajar</b>. Pasaran macam permainan Monopoly — ada strategi, peraturan dan kebarangkalian yang boleh dipelajari.”</p></div><div class=\"nc\"><h3>William Eckhardt</h3><p>“Bakat trading itu <b>semula jadi</b>. Tak semua orang boleh.” (rakan kongsi &amp; ahli matematik)</p></div><ul><li>Iklan dibuat di akhbar untuk latihan <b>commodity futures</b> di C&amp;D Commodities — <b>tiada pengalaman diperlukan</b>. Sambutan sedikit sahaja; ramai tak percaya jalan mudah ke kejayaan wujud.</li><li>Dennis pilih orang yang berani ambil <b>risiko terkira</b>, bukan berdasarkan IQ atau latar belakang hebat.</li><li>Dennis lihat duit sebagai <b>alat mengira markah</b>, bukan sesuatu untuk dilekatkan emosi.</li><li>Eckhardt percaya orang yang bermula dengan modal kecil lebih faham nilai risiko dan kerugian.</li></ul>"}, {"n": 6, "k": "Bab 2 · Prince of the Pit", "t": "Siapa Richard Dennis?", "h": "<ul><li>Membesar dalam keluarga kelas pekerja di Chicago — <b>bukan anak orang kaya</b>.</li><li>Awal-awal trading, dia <b>gagal</b>. Dari situ dia belajar terima kerugian sebagai sebahagian permainan.</li><li>Dipengaruhi ahli falsafah empirik (David Hume, John Locke): <b>percaya pada bukti &amp; pemerhatian</b>, bukan andaian.</li><li>Bermula di lantai MidAmerica Exchange → menjadi gergasi di Chicago Board of Trade → bina C&amp;D Commodities.</li><li>Pada 1986 sahaja dia untung <b>USD 80 juta</b>.</li></ul><div class=\"nc nc-amber\"><h3>Sikap Dennis</h3><p>Tidur lena walaupun rugi jutaan sehari. Tenang menerima risiko = kunci bertahan dalam pasaran ganas.</p></div><div class=\"nc nc-rust\"><h3>Cabaran</h3><p>Urus duit pelanggan jauh lebih sukar — pelanggan panik bila drawdown, tak faham risiko sebenar.</p></div>"}, {"n": 7, "k": "Bab 2 · Minda Dennis", "t": "5 cara Dennis berfikir yang trader FCPO patut tiru", "h": "<div class=\"nc\"><p class=\"nn\">1</p><p><b>Majoriti selalunya salah.</b> Keuntungan datang bila kita berani berbeza dengan orang ramai.</p></div><div class=\"nc\"><p class=\"nn\">2</p><p><b>Jangan telan bulat-bulat</b> “kebijaksanaan biasa” pasaran. Uji sendiri.</p></div><div class=\"nc\"><p class=\"nn\">3</p><p><b>Sikap terhadap duit mesti luar biasa.</b> Duit = markah, bukan emosi.</p></div><div class=\"nc\"><p class=\"nn\">4</p><p><b>Mesti pernah lalui kegagalan</b> dalam minda — bersedia untuk rugi sebelum masuk.</p></div><div class=\"nc\"><p class=\"nn\">5</p><p><b>Pelabur hebat guna maklumat secara berbeza</b>, bukan dapat maklumat lebih baik.</p></div><div class=\"nc nc-dark\"><p>💡 <b>Untuk FCPO:</b> bila semua orang dalam group Telegram yakin harga CPO “confirm naik”, itu bukan isyarat untuk anda. Isyarat anda datang dari <b>peraturan bertulis</b> anda sahaja.</p></div>"}, {"n": 8, "k": "Bab 3 · The Turtles", "t": "Bagaimana Turtle dipilih dan dilatih", "h": "<div class=\"nc\"><h3>Latar belakang pelbagai</h3><p>Pengawal keselamatan, broker yang bergelut, pemain blackjack, pemain piano, graduan universiti — campur-aduk sengaja.</p></div><div class=\"nc\"><h3>Ciri yang dicari</h3><ul><li>Kebolehan matematik</li><li>Mahu belajar</li><li>Emosi kental, ego rendah</li><li>Cara fikir luar biasa</li></ul></div><div class=\"nc\"><h3>Proses temuduga</h3><p>Ujian betul/salah tentang prinsip trading, esei peribadi, sesi temuduga santai tapi memaksa calon berfikir kritis.</p></div><div class=\"nc nc-amber\"><h3>Topik PERTAMA latihan = pengurusan risiko</h3><p>Bukan “cara nak untung” — tapi cara menghadapi kerugian &amp; situasi buruk. Inilah yang membezakan Turtle.</p></div><div class=\"nc nc-dark\"><h3>Kontrak ketat</h3><p>Turtle tandatangan perjanjian kerahsiaan &amp; sekatan bersaing. Tiada seorang pun menolak tawaran Dennis.</p></div>"}, {"n": 9, "k": "Aktiviti · Soalan Temuduga Turtle", "t": "Anda setuju atau tidak? (Jawab dulu, kemudian lihat)", "h": "<div class=\"ntf\"> 1. “Anda takkan bankrap kalau selalu ambil untung.”<span class=\"np\">TIDAK SETUJU</span> Ambil untung awal-awal = potong trend besar. Trend follower hidup dengan beberapa trend gergasi. 2. “Gerak hati (hunch) bagus untuk trading.”<span class=\"np\">TIDAK SETUJU</span> Turtle ikut peraturan, bukan rasa. Dennis: “Kebanyakan yang tak menjadi adalah keputusan berdasarkan pendapat.” 3. “Naluri semula jadi ialah panduan baik membuat keputusan.”<span class=\"np\">TIDAK SETUJU</span> Naluri manusia (takut, tamak, harap) berlawanan dengan apa yang pasaran perlukan. 4. “Susunan emosi lebih penting daripada kepintaran.”<span class=\"np\">SETUJU</span> Orang yang boleh trade 1–5 lot tanpa memikirkan duit — itulah yang berjaya. 5. “Nasib menentukan kejayaan jangka panjang.”<span class=\"np\">TIDAK SETUJU</span> Dennis: “Dalam jangka panjang, peranan nasib — sifar. Mutlak sifar.” </div>"}, {"n": 10, "k": "Bahagian 2 · Bab 4", "t": "Falsafah Turtle", "h": "<p>Cara berfikir sebelum belajar sebarang peraturan. Tanpa falsafah ini, peraturan secanggih mana pun akan dilanggar.</p>"}, {"n": 11, "k": "Bab 4 · Kaedah Saintifik", "t": "Jadi saintis dulu, baru jadi trader", "h": "<div class=\"nc\"><p class=\"nn\">1</p><h3>Tanya</h3><p>Apa soalan sebenar? Cth: “Adakah breakout 20 hari FCPO menguntungkan?”</p></div><div class=\"nc\"><p class=\"nn\">2</p><h3>Hipotesis</h3><p>“Jika beli bila harga pecah paras tertinggi 20 hari, purata untung &gt; purata rugi.”</p></div><div class=\"nc\"><p class=\"nn\">3</p><h3>Uji</h3><p>Backtest data lama, kemudian paper trade.</p></div><div class=\"nc\"><p class=\"nn\">4</p><h3>Analisis</h3><p>Lihat nombor. Terima atau tolak — tanpa emosi.</p></div><div class=\"nc nc-dark\"><h3>Ikut trend (Trend Following)</h3><p>Diasaskan dari kerja Richard Donchian. Tunggu pasaran bergerak, kemudian <b>ikut</b> — jangan teka puncak atau dasar.</p></div><div class=\"nc nc-amber\"><h3>“Kenapa tak guna fundamental?”</h3><p>Dennis: “Anda tak dapat untung dari analisis fundamental. Anda untung dari beli dan jual. Kenapa tak terus ke realiti — <b>harga</b>?”</p></div>"}, {"n": 12, "k": "Bab 4 · Prinsip Teras", "t": "4 soalan yang Turtle mesti jawab setiap hari", "h": "<div class=\"nc\"><h3>Keadaan pasaran?</h3><p>Sedang trend naik, turun, atau sideways?</p></div><div class=\"nc\"><h3>Volatiliti?</h3><p>Berapa jauh harga bergerak sehari (N)?</p></div><div class=\"nc\"><h3>Ekuiti?</h3><p>Berapa modal saya <i>sekarang</i> (bukan modal asal)?</p></div><div class=\"nc\"><h3>Toleransi risiko?</h3><p>Berapa % saya sanggup rugi per dagangan?</p></div><ul><li><b>Tiada emosi</b> terhadap turun naik pasaran.</li><li><b>Konsisten</b> dan tenang — perangai sama hari untung atau rugi.</li><li><b>Proses lebih penting dari hasil</b> satu-satu trade.</li></ul><ul><li>Risiko hanya <b>peratus kecil</b> modal setiap trade.</li><li>Layan <b>untung &amp; rugi dengan serius yang sama</b>.</li><li>Spekulasi tiada had — jadi <b>lindungi modal</b> dulu.</li></ul>"}, {"n": 13, "k": "Bab 4 · Disiplin Minda", "t": "Tiga tabiat minda Turtle", "h": "<div class=\"nc\">TABIAT 1<h3>Trading “tanpa memori”</h3><p>Keputusan berdasarkan harga &amp; volatiliti <b>hari ini</b>. Lupakan rasa sakit trade semalam atau euforia minggu lepas.</p></div><div class=\"nc\">TABIAT 2<h3>Exit lebih penting dari entry</h3><p>Jangan obses harga masuk. Yang menentukan untung rugi ialah <b>bila dan bagaimana keluar</b> — ikut peraturan yang dah ditetapkan.</p></div><div class=\"nc\">TABIAT 3<h3>Terima rugi, cari peluang seterusnya</h3><p>Rugi itu kos berniaga. Jangan cuba “balas dendam” untuk dapatkan balik duit yang hilang.</p></div><div class=\"nc nc-amber\"><blockquote>“Trader yang takut rugi berada dalam bisnes yang salah.”</blockquote><p>— Petikan Bab 4</p></div>"}, {"n": 14, "k": "Bahagian 3 · Bab 5", "t": "Peraturan Dagangan Turtle", "h": "<p>Bahagian paling teknikal. Kita akan kira semuanya dalam Ringgit menggunakan kontrak FCPO.</p>"}, {"n": 15, "k": "Bab 5 · Asas", "t": "Dua alat asas sebelum mula", "h": "<div class=\"nc\"><h3>Stop order</h3><p>Arahan yang <b>menjadi market order</b> bila harga tertentu disentuh. Digunakan untuk:</p><ul><li>Masuk bila breakout berlaku</li><li>Hadkan rugi (stop loss)</li><li>Kunci untung bila trend berpusing</li></ul></div><div class=\"nc\"><h3>Moving average</h3><p>Purata harga bergerak yang <b>melicinkan “bising” harian</b> dan menonjolkan trend jangka panjang. Turtle juga melihat volatiliti sebagai satu proses purata bergerak.</p></div><div class=\"nc nc-dark\"><h3>Ralat Jenis I &amp; Jenis II</h3><p><b>Jenis I</b> — menolak peluang yang sebenarnya betul (terlepas trend besar).</p><p><b>Jenis II</b> — menerima peluang palsu (masuk false breakout, kena stop).</p><p>Pilihan Turtle: <b>lebih baik rugi kecil berkali-kali daripada terlepas SATU untung besar.</b></p></div>"}, {"n": 16, "k": "Bab 5 · Edge & Expectancy", "t": "Kenali “edge” anda — macam purata pukulan pemain besbol", "h": "<p class=\"nf\">Expectancy = (<em>% Menang</em> × Purata Untung) − (<em>% Kalah</em> × Purata Rugi)</p><div class=\"nc\"><h3>Contoh sistem trend FCPO</h3><div class=\"ntw\"><table><tr><td>Kadar menang</td><td>35%</td></tr><tr><td>Purata untung (trade menang)</td><td>RM 4,500</td></tr><tr><td>Kadar kalah</td><td>65%</td></tr><tr><td>Purata rugi (trade kalah)</td><td>RM 1,500</td></tr><tr><td><b>Expectancy setiap trade</b></td><td><b>+RM 600</b></td></tr></table></div><p>(0.35 × 4,500) − (0.65 × 1,500) = 1,575 − 975 = 600. Angka andaian untuk latihan.</p></div><div class=\"nc nc-amber\"><p><b>Lihat:</b> kalah 65% pun masih untung! Trend follower biasanya <b>lebih banyak kalah dari menang</b> — tapi untungnya besar, ruginya kecil.</p></div><div class=\"nc\"><blockquote>“Anda tak boleh bertaruh kalau anda tak tahu edge anda.”</blockquote><p>— Tip #1, Bab 5</p></div>"}, {"n": 17, "k": "Bab 5 · Entry", "t": "Breakout: beli bila harga buat paras tertinggi baru", "h": "<svg aria-label=\"Rajah breakout\" class=\"nsvg\" role=\"img\" viewBox=\"0 0 560 360\"><line stroke=\"#d8952a\" stroke-dasharray=\"7 6\" stroke-width=\"2.5\" x1=\"30\" x2=\"380\" y1=\"150\" y2=\"150\"></line><text fill=\"#9a6410\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" x=\"34\" y=\"140\">Paras tertinggi 20 hari</text><line stroke=\"#b0452b\" stroke-dasharray=\"4 6\" stroke-width=\"2\" x1=\"30\" x2=\"380\" y1=\"262\" y2=\"262\"></line><text fill=\"#b0452b\" font-family=\"Inter\" font-size=\"14\" font-weight=\"700\" x=\"34\" y=\"282\">Paras terendah</text><polyline fill=\"none\" points=\"30,220 60,190 90,240 120,170 150,230 180,155 210,250 240,200 270,175 300,230 330,195 360,165 385,140 410,120 440,130 470,95 500,80 530,55\" stroke=\"#163d2f\" stroke-width=\"3\"></polyline><circle cx=\"381\" cy=\"150\" fill=\"#d8952a\" r=\"9\"></circle><text fill=\"#163d2f\" font-family=\"Inter\" font-size=\"15\" font-weight=\"800\" x=\"392\" y=\"176\">BELI (breakout)</text><text fill=\"#5b6a62\" font-family=\"Inter\" font-size=\"13\" x=\"120\" y=\"330\">Harga berlegar dalam julat… kemudian pecah ke atas</text></svg><ul><li>Lupakan “beli murah, jual mahal”. Turtle <b>beli kekuatan</b> — bila harga pecah paras tertinggi N hari. Jual (short) bila pecah paras terendah.</li><li>Fokus <b>hanya pada pergerakan harga</b>, bukan berita.</li><li>Terima bahawa banyak breakout akan gagal — itu kos menunggu trend besar.</li></ul><div class=\"nc nc-amber\"><blockquote>“Entry yang paling ringkas mesti terus berfungsi.”</blockquote></div>"}, {"n": 18, "k": "Bab 5 · Dua Sistem", "t": "Sistem 1 (jangka pendek) & Sistem 2 (jangka panjang)", "h": "<div class=\"ntw\"><table><tr><th></th><th>Sistem 1</th><th>Sistem 2</th></tr><tr><td><b>Entry</b></td><td>Pecah paras tertinggi / terendah <b>20 hari</b></td><td>Pecah paras tertinggi / terendah <b>55 hari</b></td></tr><tr><td><b>Exit (ambil untung)</b></td><td>Pecah arah berlawanan <b>10 hari</b></td><td>Pecah arah berlawanan <b>20 hari</b></td></tr><tr><td><b>Stop loss</b></td><td colspan=\"2\"><b>2N</b> dari harga masuk (lihat slaid seterusnya)</td></tr><tr><td><b>Penapis</b></td><td>Abaikan isyarat jika breakout sebelumnya <b>menang</b>. (Tetapi masuk di breakout 55 hari supaya tak terlepas trend besar.)</td><td>Tiada penapis — ambil semua isyarat</td></tr></table></div><div class=\"nc\"><p><b>Nota guru:</b> Ringkasan buku menyebut dua sistem + penapis. Angka 20/55/10/20 di atas ialah <b>parameter klasik Turtle</b> yang dihuraikan dalam Bab 5 versi penuh dan peraturan Turtle yang diterbitkan.</p></div><div class=\"nc nc-amber\"><p><b>Penting:</b> Buku sendiri mengakui “pemilihan nilai ini sentiasa subjektif”. Uji sendiri pada data FCPO sebelum guna — <b>percaya, tapi sahkan</b>.</p></div>"}, {"n": 19, "k": "Bab 5 · Volatiliti “N”", "t": "N = berapa jauh FCPO bergerak dalam sehari", "h": "<p class=\"nf\">N = purata <em>True Range</em> 20 hari (ATR 20)</p><div class=\"nc\"><h3>True Range = yang paling besar antara:</h3><ul><li>High hari ini − Low hari ini</li><li>High hari ini − Close semalam</li><li>Close semalam − Low hari ini</li></ul><p>Dalam platform carta, guna indikator <b>ATR(20)</b> pada carta harian.</p></div><div class=\"nc nc-dark\"><h3>Tukar N kepada Ringgit (FCPO)</h3><p>1 mata FCPO = RM1/tan × 25 tan = <b>RM25 sekontrak</b></p><p>Contoh: N = 60 mata<br/>→ 60 × RM25 = <b>RM1,500</b><br/>pergerakan harian biasa bagi 1 kontrak</p></div><p>Kenapa penting? N membolehkan saiz posisi <b>menyesuaikan diri</b> — pasaran ganas = kontrak lebih sedikit; pasaran tenang = boleh lebih banyak.</p>"}, {"n": 20, "k": "Bab 5 · Saiz Posisi", "t": "Berapa kontrak FCPO patut saya buka?", "h": "<p class=\"nf\">1 Unit = (<em>1% ekuiti</em>) ÷ (N × RM25)</p><div class=\"nc\"><h3>Contoh A — Akaun RM150,000</h3><div class=\"ntw\"><table><tr><td>1% ekuiti</td><td>RM1,500</td></tr><tr><td>N = 60 → 60 × RM25</td><td>RM1,500</td></tr><tr><td><b>Saiz 1 unit</b></td><td><b>1 kontrak</b></td></tr></table></div></div><div class=\"nc nc-rust\"><h3>Contoh B — Akaun RM30,000</h3><div class=\"ntw\"><table><tr><td>1% ekuiti</td><td>RM300</td></tr><tr><td>N = 60 → 60 × RM25</td><td>RM1,500</td></tr><tr><td><b>Saiz 1 unit</b></td><td><b>0.2 → 0 kontrak</b></td></tr></table></div></div><div class=\"nc nc-amber\"><p><b>Kebenaran pahit:</b> FCPO ialah kontrak besar. Jika kiraan beri 0, <b>jangan paksa masuk 1 lot</b> — itu bermakna anda ambil risiko 5× ganda dari yang dirancang. Pilihan: kumpul modal, paper trade dulu, atau tunggu N lebih kecil. Sentiasa <b>bundarkan ke bawah</b>.</p></div>"}, {"n": 21, "k": "Bab 5 · Stop Loss", "t": "Stop 2N: setiap trade rugi maksimum ~2% akaun", "h": "<div class=\"nc\"><h3>Contoh (sambungan Contoh A)</h3><div class=\"ntw\"><table><tr><td>Breakout 20 hari — beli</td><td>RM4,250</td></tr><tr><td>2N = 2 × 60 mata</td><td>120 mata</td></tr><tr><td>Stop loss</td><td><b>RM4,130</b></td></tr><tr><td>Rugi jika kena stop (1 kontrak)</td><td>120 × RM25 = <b>RM3,000</b></td></tr><tr><td>% daripada akaun RM150,000</td><td><b>2%</b></td></tr></table></div><p>Harga FCPO di sini ialah contoh, bukan ramalan.</p></div><div class=\"nc nc-dark\"><p>Stop diletak <b>sebelum</b> masuk, dan <b>tidak dilonggarkan</b>. Hanya boleh digerakkan ke arah untung.</p></div><div class=\"nc\"><blockquote>“Yang penting ialah hadkan risiko portfolio. Trade akan uruskan dirinya sendiri.”</blockquote><p>— Bab 5</p></div>"}, {"n": 22, "k": "Bab 5 · Piramid", "t": "Tambah posisi bila menang, bukan bila kalah", "h": "<div class=\"ntw\"><table><tr><th>Unit</th><th>Harga masuk</th><th>Stop semua unit</th></tr><tr><td>1</td><td>4,250</td><td>4,130</td></tr><tr><td>2 (+½N)</td><td>4,280</td><td>4,160</td></tr><tr><td>3 (+½N)</td><td>4,310</td><td>4,190</td></tr><tr><td>4 (+½N) — maksimum</td><td>4,340</td><td><b>4,220</b></td></tr></table></div><p>N = 60, jadi ½N = 30 mata. Setiap unit baru → semua stop naik ke 2N di bawah entry terakhir.</p><ul><li><b>Piramid</b> = tambah unit pada trade yang sedang untung untuk besarkan keuntungan dari trend.</li><li>Parameter klasik: tambah 1 unit setiap harga bergerak <b>½N</b> memihak, <b>maksimum 4 unit</b> satu pasaran.</li><li>Stop dinaikkan bersama — untung terkumpul dilindungi.</li><li>Saiz dikira semula ikut volatiliti supaya risiko kekal konsisten.</li></ul><div class=\"nc nc-rust\"><p><b>Haram bagi Turtle:</b> “average down” — tambah lot pada posisi yang sedang rugi.</p></div>"}, {"n": 23, "k": "Bab 5 · Drawdown & Portfolio", "t": "Kecilkan saiz bila akaun jatuh, pelbagaikan pasaran", "h": "<div class=\"nc\"><h3>Peraturan drawdown</h3><p>Turtle mengurangkan risiko bila akaun dalam drawdown. Parameter klasik: setiap kali akaun jatuh <b>10%</b>, kira saiz posisi seolah-olah akaun <b>20% lebih kecil</b>.</p><div class=\"ntw\"><table><tr><td>Akaun asal</td><td>RM150,000</td></tr><tr><td>Jatuh 10% → baki</td><td>RM135,000</td></tr><tr><td>Kira saiz guna</td><td><b>RM120,000</b></td></tr></table></div></div><div class=\"nc\"><h3>Kepelbagaian portfolio</h3><ul><li>Turtle dagang banyak pasaran yang <b>tidak berkorelasi</b> untuk kurangkan risiko keseluruhan.</li><li>Imbangkan posisi <b>long dan short</b>.</li><li>Pasaran berkait rapat dikira sebagai risiko yang sama.</li></ul><p><b>Untuk FCPO:</b> FCPO bergerak seiring minyak soya CBOT &amp; minyak sawit Dalian. Long FCPO + long minyak soya ≈ risiko berganda, bukan pelbagai.</p></div><div class=\"nc nc-dark\"><p>🔁 <b>Latihan berterusan:</b> kejayaan trading macam sukan lain — perlu latihan konsisten dan penambahbaikan. “Untuk Turtle trading berjaya, anda mesti <b>percaya, tapi sahkan</b>.”</p></div>"}, {"n": 24, "k": "Ringkasan Bab 5", "t": "Sistem lengkap = 6 jawapan bertulis", "h": "<p>“Kalau sistem anda beri entry, exit, berapa banyak nak bertaruh, dan menyesuaikan diri dengan modal &amp; volatiliti semasa — <b>tiada analisis lain diperlukan</b>.” (Bab 6)</p><div class=\"nc\"><h3>1. Pasaran</h3><p>Apa yang saya dagang? (FCPO bulan ketiga)</p></div><div class=\"nc\"><h3>2. Saiz posisi</h3><p>1% ekuiti ÷ (N × RM25), bundar ke bawah</p></div><div class=\"nc\"><h3>3. Entry</h3><p>Breakout 20 / 55 hari</p></div><div class=\"nc\"><h3>4. Stop loss</h3><p>2N dari entry</p></div><div class=\"nc\"><h3>5. Exit</h3><p>Breakout berlawanan 10 / 20 hari</p></div><div class=\"nc\"><h3>6. Taktik</h3><p>Piramid ½N, maks 4 unit, kurangkan saiz bila drawdown</p></div>"}, {"n": 25, "k": "Bahagian 4 · Bab 6–10", "t": "Realiti di Sebalik Kejayaan", "h": "<p>Peraturan sama, tapi hasil berbeza. Apa yang berlaku di dalam pejabat Turtle — dan kepada guru mereka sendiri.</p>"}, {"n": 26, "k": "Bab 6 · In the Womb", "t": "Hidup sebagai Turtle: banyak menunggu, sedikit bertindak", "h": "<ul><li>Pejabat ringkas, <b>hampir tiada pengawasan</b>. Turtle belajar sendiri dan berkembang secara bebas.</li><li>Latar belakang &amp; pandangan politik berbeza — tetapi wujud semangat “satu suku”: saling sokong, saling bersaing.</li><li>Ada tempoh panjang <b>tiada isyarat langsung</b>. Turtle belajar disiplin untuk <b>tidak buat apa-apa</b>.</li><li>Prestasi awal turun naik → ramai mula ragu-ragu dengan sistem. Kejayaan kemudiannya membuktikan sistem itu.</li></ul><div class=\"nc nc-amber\"><blockquote>“Dalam tahun biasa, kami buat <b>semua</b> duit kami dalam lebih kurang tempoh tiga minggu.”</blockquote><p>— Seorang Turtle, Bab 6</p></div><div class=\"nc nc-dark\"><p><b>Maksudnya untuk anda:</b> jika anda tak ada dalam pasaran semasa trend besar FCPO tiba (cth. kejutan cuaca El Niño, polisi eksport), setahun kerja boleh jadi sia-sia. Jangan skip isyarat.</p></div>"}, {"n": 27, "k": "Bab 7 · Who Got What to Trade", "t": "Pilih kasih, ketidakadilan, dan risiko yang tersembunyi", "h": "<div class=\"nc\"><h3>Peruntukan tak sama</h3><p>Dennis beri jumlah dana berbeza kepada setiap Turtle. Ada yang untung baik tapi dapat dana kecil; ada yang rugi tapi dapat lebih.</p></div><div class=\"nc\"><h3>Kes Curtis Faith</h3><p>Turtle termuda, dapat peruntukan paling besar walaupun gayanya agresif dan kadang-kadang langgar peraturan. Timbul syak pilih kasih.</p></div><div class=\"nc nc-rust\"><h3>Penemuan kajian</h3><p>Sekumpulan Turtle buat kajian sendiri: mereka sebenarnya dagang pada <b>dua kali ganda</b> tahap risiko yang disyorkan. Dennis arahkan saiz posisi dikurangkan.</p></div><div class=\"nc nc-dark\"><h3>Pengajaran</h3><ul><li>Ukur prestasi secara <b>objektif</b> — nombor hitam putih, bukan perasaan.</li><li>Semak semula risiko sebenar anda secara berkala. Ramai trader tak sedar mereka ambil risiko 2× dari yang disangka.</li><li>Jangan bandingkan untung RM anda dengan orang lain yang modalnya berbeza — bandingkan <b>%</b> dan disiplin.</li></ul></div>"}, {"n": 28, "k": "Bab 8 · Game Over", "t": "Guru pun tumbang bila langgar peraturan sendiri", "h": "<ul><li>Dennis risau berlebihan tentang “skid” (slippage) — dan dalam hati dia seorang <b>contrarian</b>, bercanggah dengan sistem ikut trend yang dia ajar.</li><li>April 1988: dana awam Dennis jatuh <b>55%</b>. Ditambah kematian bapanya.</li><li>Rakan &amp; pelajar perhati: Dennis dagang dengan saiz <b>jauh lebih besar</b> dari had yang dia kenakan pada Turtle.</li><li>Program Turtle ditutup secara mengejut melalui <b>satu faks</b>. Pelanggan saman; kes diselesaikan di luar mahkamah.</li><li>Ironinya: Turtle (risiko lebih kecil) masih untung.</li></ul><div class=\"nc nc-rust\"><h3>Pengajaran #1</h3><p>Disiplin tidak kekal selamanya. Ia mesti dijaga <b>setiap hari</b> — tak kira berapa hebat rekod lalu.</p></div><div class=\"nc\"><h3>Pengajaran #2</h3><p>Jika urus duit orang (atau akaun prop), pastikan mereka <b>faham drawdown</b> yang mungkin berlaku.</p></div><div class=\"nc nc-amber\"><blockquote>“Tiba-tiba semuanya tamat. Secepat itu.”</blockquote></div>"}, {"n": 29, "k": "Bab 9–10 · Selepas Graduasi", "t": "Setiap Turtle pilih jalan sendiri", "h": "<div class=\"nc\"><h3>Jerry Parker</h3><p>Kurangkan leverage supaya pelabur institusi selesa. Bina firma sendiri dengan cepat.</p></div><div class=\"nc\"><h3>Tom Shanks &amp; Liz Cheval</h3><p>Kekal risiko tinggi, pulangan tinggi. “Volatiliti yang cipta pulangan tinggi.”</p></div><div class=\"nc nc-rust\"><h3>Russell Sands</h3><p>Jual peraturan Dennis kepada umum. Dikecam rakan Turtle sebagai khianat amanah.</p></div><div class=\"nc nc-dark\"><h3>Dennis kembali</h3><p>Buka Dennis Trading Group 1994; pulangan &gt;100% pada 1995 &amp; 1996 — guna sistem mekanikal. Ditutup 2000 selepas rugi besar.</p></div><div class=\"nc nc-amber\"><p><b>Fakta penting:</b> semua model ikut trend biasanya untung &amp; rugi dalam <b>pasaran yang sama, waktu yang sama</b>. Edge bukan dari rahsia entry — tapi dari disiplin &amp; pengurusan risiko.</p></div><div class=\"nc\"><blockquote>“Konspirasi terbesar ialah tiada konspirasi. Tiada siapa nak jatuhkan anda. Pasaran tak peduli.”</blockquote><p>— Bab 9</p></div>"}, {"n": 30, "k": "Bahagian 5 · Bab 11–14", "t": "Siapa Berjaya, Siapa Gagal — dan Kenapa", "h": "<p>Ilmu yang sama, keputusan berbeza. Perbezaannya ialah watak, ketahanan dan pilihan.</p>"}, {"n": 31, "k": "Bab 11 · Seizing Opportunity", "t": "Jerry Parker: trader + usahawan", "h": "<ul><li>Mula sebagai Turtle dengan <b>rugi</b>, kemudian bina kekayaan sehingga dianggarkan USD 770 juta.</li><li>Ciri usahawan: <b>tak ikut arus, tak terbawa emosi, berani ambil risiko, berdikari</b>.</li><li>Trading juga perniagaan: sistem perakaunan, undang-undang, pemasaran, rangkaian (cth. kerjasama dengan James River Capital).</li><li>Kritik keras terhadap <b>mean reversion</b>: “Banjir 100 tahun sebenarnya berlaku setiap 2–3 tahun — dan ia menghapuskan kekayaan.” (cth. Amaranth)</li></ul><div class=\"nc nc-amber\"><blockquote>“Penting untuk hidup dengan seseorang yang berkata, ‘Tak apa rugi duit.’”</blockquote></div><div class=\"nc\"><blockquote>“Mentor yang jujur dan rendah diri ialah perkara terbaik. Buat perkara yang betul setiap hari.”</blockquote></div><div class=\"nc nc-dark\"><p><b>Untuk FCPO:</b> jangan “tangkap pisau jatuh” sebab rasa harga CPO “dah terlalu murah”. Harga boleh terus jatuh lebih jauh dari logik.</p></div>"}, {"n": 32, "k": "Bab 12 · Failure Is a Choice", "t": "Kegagalan ialah satu pilihan", "h": "<div class=\"nc\"><h3>Kenapa ada Turtle yang gagal?</h3><p>Bukan kerana kurang pandai — tetapi <b>ego, jangkaan yang salah, dan tak mampu ikut sistem</b>.</p></div><div class=\"nc nc-rust\"><h3>Kisah Curtis Faith</h3><p>Turtle paling berjaya semasa program, tapi selepas itu bergelut: perniagaan gagal, rugi trading, dana Acceleration Capital bermasalah. Kejayaan lalu ≠ jaminan masa depan.</p></div><div class=\"nc nc-dark\"><blockquote>“Trader yang baik guna setiap ons kepintaran untuk <b>mencipta</b> sistem — kemudian jadi ‘bodoh’ ketika <b>mengikutnya</b>.”</blockquote></div><div class=\"nc nc-amber\"><p><b>Pendekatan “dua personaliti”:</b> masa bina sistem — jadi saintis. Masa jalankan sistem — jadi <b>dinding batu</b>, tanpa emosi.</p></div><div class=\"nc\"><blockquote>“Legenda itu dilahirkan. Tapi trader yang <b>baik</b> boleh dibentuk.”</blockquote></div>"}, {"n": 33, "k": "Bab 13 · Second-Generation Turtles", "t": "Salem Abraham: bukti ilmu ini boleh diwarisi", "h": "<ul><li>Anak muda dari pekan kecil Canadian, Texas. Asalnya nak buka bisnes mel-pesanan.</li><li>Kebetulan berjumpa Jerry Parker → belajar daripada Turtle, <b>bukan daripada Dennis</b>.</li><li>Mula dengan akaun kecil. Kena teruk dalam crash 1987 — tetapi terus bertahan dan belajar.</li><li>Dapat modal keluarga, kemudian Commodities Corporation melabur. Kemudian barulah dilatih terus oleh Dennis &amp; Eckhardt.</li><li>Faham kedua-dua sisi: <b>statistik</b> dan <b>psikologi</b> trading.</li></ul><div class=\"nc nc-amber\"><blockquote>“Kalau nak berjaya, kenal pasti siapa yang dah berjaya dan apa yang mereka buat.”</blockquote></div><div class=\"nc\"><p><b>Risiko macam kereta laju:</b> ada enjin kuat tak bermakna mesti tekan minyak habis.</p></div><div class=\"nc\"><blockquote>“Kalau buat 30% setahun, orang akan beratur cari anda. Kurangkan leverage.”</blockquote></div>"}, {"n": 34, "k": "Bab 14 · Model Greatness", "t": "Kesimpulan buku: didikan mengatasi bakat", "h": "<div class=\"nc\"><h3>Ketahanan mental</h3><p>Kebanyakan gagal sebab berhenti terlalu awal, bukan sebab sistem salah.</p></div><div class=\"nc\"><h3>Belajar berterusan</h3><p>Baca tanpa henti — seperti Charlie Munger &amp; Eddie Lampert.</p></div><div class=\"nc\"><h3>Latihan sengaja</h3><p>Komitmen macam pakar bedah — ulang, nilai, perbaiki.</p></div><div class=\"nc\"><h3>Pasaran terbuka</h3><p>Pasaran tak kisah latar belakang anda. Ilmu &amp; tekad yang menentukan.</p></div><div class=\"nc nc-dark\"><blockquote>“Anda mesti mampu tarik picu ketika darah membanjiri Wall Street — terutama jika darah itu darah anda sendiri.”</blockquote><p>— Bab 14</p></div><p>Cabaran sebenar bukan belajar peraturan — tapi menjadi <b>usahawan trading</b> yang boleh berdiri sendiri tanpa “Dennis” di belakang.</p>"}, {"n": 35, "k": "Petikan Emas", "t": "10 ayat untuk ditampal di skrin trading anda", "h": "<p>1. “Lebih baik ambil banyak rugi kecil daripada terlepas satu untung besar.”</p><p>2. “Dalam jangka panjang, peranan nasib — sifar.”</p><p>3. “Untuk ikut prinsip tanpa biar takut, tamak &amp; harapan masuk campur — itu berenang melawan arus sifat manusia.”</p><p>4. “Anda mesti ada strategi, tahu cara ia berfungsi, dan ikut sampai habis.”</p><p>5. “Bila trade rugi, katakan: ‘Ia nampak betul pada masa itu.’”</p><p>6. “Di hujung hari, nombor itu hitam putih. Sama ada anda untung atau tidak.”</p><p>7. “Trend ialah kawan kita; hari ini mungkin ia kekasih yang kejam.”</p><p>8. “Rancangan baik yang dilaksana sekarang lebih baik dari rancangan sempurna minggu depan.” — Patton</p><p>9. “Orang yang hebat dan bertahan lama itu tegar. Bila hidup melawan, mereka tetap dengan permainan mereka.”</p><p>10. “Didikan mengatasi bakat semula jadi.”</p>"}, {"n": 36, "k": "Bahagian 6", "t": "Aplikasi pada FCPO & Tindakan Selepas Seminar", "h": "<p>Dari teori kepada rutin harian. Inilah yang anda buat mulai esok.</p>"}, {"n": 37, "k": "Kenali Instrumen", "t": "FCPO dalam satu slaid", "h": "<div class=\"ntw\"><table><tr><td>Bursa</td><td>Bursa Malaysia Derivatives</td></tr><tr><td>Saiz kontrak</td><td><b>25 tan metrik</b></td></tr><tr><td>Tick minimum</td><td>RM1 / tan = <b>RM25 sekontrak</b></td></tr><tr><td>Sesi pagi</td><td>10:30 pg – 12:30 tgh</td></tr><tr><td>Sesi petang</td><td>2:30 ptg – 6:00 ptg</td></tr><tr><td>Sesi malam (T+1)</td><td>9:00 mlm – 11:30 mlm (Isnin–Khamis)</td></tr><tr><td>Had harga harian</td><td>10% (boleh melebar ke 15% selepas cooling-off)</td></tr><tr><td>Penyelesaian</td><td><b>Penghantaran fizikal</b> (MSPO)</td></tr></table></div><div class=\"nc nc-amber\"><h3>Kontrak paling aktif</h3><p>Kebanyakan dagangan tertumpu pada <b>bulan ketiga</b>. Guna kontrak ini untuk carta &amp; isyarat, dan <b>roll</b> bila tumpuan berpindah.</p></div><div class=\"nc nc-rust\"><h3>Awas penghantaran fizikal</h3><p>Jangan simpan posisi sehingga bulan spot/penghantaran. Tutup atau roll lebih awal.</p></div><div class=\"nc\"><p>Margin berubah-ubah — semak dengan broker anda. Spesifikasi disahkan dari laman Bursa/broker; sentiasa rujuk sumber rasmi terkini.</p></div>"}, {"n": 38, "k": "Realiti Trend Following di FCPO", "t": "5 perkara yang buku tak sebut tentang FCPO", "h": "<div class=\"nc\"><h3>1. Whipsaw</h3><p>FCPO kerap sideways. Akan ada siri false breakout berturut-turut. Ini normal — sebab itu saiz kecil.</p></div><div class=\"nc\"><h3>2. Gap sesi malam</h3><p>Berita (data MPOB, eksport, harga soya CBOT) boleh buat harga lompat melepasi stop anda.</p></div><div class=\"nc\"><h3>3. Had harga (limit)</h3><p>Bila pasaran kena had 10%, stop mungkin tak terisi. Ini “skid” yang Dennis risaukan.</p></div><div class=\"nc\"><h3>4. Rollover</h3><p>Bila tukar bulan kontrak, harga berbeza. Kira semula paras breakout guna kontrak baru.</p></div><div class=\"nc\"><h3>5. Satu pasaran sahaja</h3><p>Turtle asal pelbagaikan banyak pasaran. Trader FCPO sahaja lebih terdedah — jadi kekalkan risiko lebih rendah.</p></div><div class=\"nc nc-dark\"><h3>Untuk scalper / SMC</h3><p>Sistem Turtle guna carta <b>harian</b>. Kalau anda scalper, anda masih boleh pinjam: risiko tetap %, saiz ikut volatiliti, stop wajib, jurnal. Uji setiap kaedah <b>berasingan</b>.</p></div>"}, {"n": 39, "k": "Tindakan · Rutin Harian", "t": "Rutin harian trader Turtle FCPO (15 minit)", "h": "<div class=\"nrow\"><b class=\"nstep\">1</b><p><b>Selepas pasaran tutup (6 ptg):</b> kemas kini data harian kontrak bulan ketiga.</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><p><b>Kira N</b> (ATR 20) dan nilai ringgitnya: N × RM25.</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><p><b>Tanda paras:</b> tertinggi/terendah 20 &amp; 55 hari, exit 10 &amp; 20 hari.</p></div><div class=\"nrow\"><b class=\"nstep\">4</b><p><b>Kira saiz unit</b> guna ekuiti semasa (ingat peraturan drawdown).</p></div><div class=\"nrow\"><b class=\"nstep\">5</b><p><b>Pasang stop order</b> untuk entry, stop loss 2N dan paras piramid ½N.</p></div><div class=\"nrow\"><b class=\"nstep\">6</b><p><b>Isi jurnal:</b> isyarat, tindakan, sebab, emosi, adakah ikut peraturan?</p></div><div class=\"nrow\"><b class=\"nstep\">7</b><p><b>Tutup carta.</b> Jangan pantau setiap tick — biar order bekerja.</p></div><div class=\"nc nc-amber\"><p><b>KPI utama bukan untung</b> — tetapi <b>% hari anda ikut peraturan 100%</b>. Sasaran: 100%.</p></div>"}, {"n": 40, "k": "Tindakan · Pelan 90 Hari", "t": "Dari peserta seminar kepada trader bersistem", "h": "<div class=\"nc\"><span class=\"np\">MINGGU 1</span><h3>Sediakan</h3><ul><li>Buka carta harian FCPO bulan ketiga</li><li>Pasang Donchian 20/55/10 + ATR 20</li><li>Tulis pelan trading 1 muka surat (6 jawapan)</li></ul></div><div class=\"nc\"><span class=\"np\">MINGGU 2–4</span><h3>Backtest</h3><ul><li>Uji 3 tahun data secara manual</li><li>Catat setiap isyarat dalam spreadsheet</li><li>Kira % menang, purata untung/rugi, expectancy, drawdown terbesar</li></ul></div><div class=\"nc\"><span class=\"np\">BULAN 2–3</span><h3>Paper trade</h3><ul><li>Jalankan rutin harian setiap hari</li><li>Order demo/kertas sahaja</li><li>Semakan mingguan: berapa kali langgar peraturan?</li></ul></div><div class=\"nc nc-dark\"><span class=\"np\">SELEPAS 90 HARI</span><h3>Live kecil</h3><ul><li>Hanya jika expectancy positif &amp; disiplin ≥ 95%</li><li>Risiko ≤ 1% per unit</li><li>Kekal 1 unit sehingga 20 trade live</li></ul></div><div class=\"nc nc-amber\"><p><b>Cari “suku” anda:</b> bentuk kumpulan 3–5 rakan seminar. Kongsi jurnal mingguan. Turtle berjaya sebahagiannya kerana sokongan kumpulan.</p></div><div class=\"nc\"><p><b>Bacaan lanjut:</b><i>Market Wizards</i> (Jack Schwager), <i>Way of the Turtle</i> (Curtis Faith), <i>Trend Following</i> (Michael Covel).</p></div>"}, {"n": 41, "k": "Tindakan · Templat Jurnal", "t": "Satu baris untuk setiap trade", "h": "<div class=\"ntw\"><table><tr><th>Tarikh</th><th>Kontrak</th><th>Sistem</th><th>Entry</th><th>N</th><th>Stop 2N</th><th>Lot</th><th>Risiko %</th><th>Exit &amp; sebab</th><th>P/L RM</th><th>Ikut rules?</th></tr><tr><td>contoh</td><td>FCPO bln-3</td><td>S1 long</td><td>4,250</td><td>60</td><td>4,130</td><td>1</td><td>2.0</td><td>Low 10 hari</td><td>+2,250</td><td>✅</td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><div class=\"nc\"><h3>Selepas setiap trade</h3><p>Apa emosi saya? Adakah saya teragak-agak? Ia “nampak betul pada masa itu”?</p></div><div class=\"nc\"><h3>Setiap minggu</h3><p>Kira % ikut peraturan, drawdown semasa, dan saiz akaun untuk kiraan unit minggu depan.</p></div><div class=\"nc\"><h3>Setiap bulan</h3><p>Kemas kini expectancy. Bandingkan dengan keputusan backtest — masih selari?</p></div>"}, {"n": 42, "k": "Tindakan · Senarai “Jangan”", "t": "8 kesilapan newbie yang Turtle tak akan buat", "h": "<div class=\"nrow\"><b class=\"nstep\">✕</b><p>Masuk tanpa tahu di mana stop loss.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Buka lot ikut “rasa” atau ikut kawan — bukan formula N.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Tambah lot pada posisi yang sedang rugi (average down).</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Ambil untung terlalu cepat kerana takut untung hilang.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Skip isyarat selepas 3–4 kali kalah berturut-turut.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Revenge trade untuk dapatkan balik duit yang hilang.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Tukar sistem setiap kali ada drawdown.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><p>Simpan posisi masuk bulan penghantaran fizikal.</p></div>"}, {"n": 43, "k": "Kuiz Penutup · Betul atau Salah?", "t": "Uji kefahaman anda", "h": "<div class=\"ntf\"> 1. Eksperimen Turtle menunjukkan bakat semula jadi lebih penting dari latihan.<span class=\"np\">SALAH</span> 2. Turtle perlu fokus pada harga entry, bukan strategi exit.<span class=\"np\">SALAH</span> 3. Topik pertama latihan Turtle ialah pengurusan risiko.<span class=\"np\">BETUL</span> 4. Turtle guna dua sistem — jangka pendek &amp; jangka panjang — dengan penapis.<span class=\"np\">BETUL</span> 5. Dennis menutup program kerana Turtle rugi teruk.<span class=\"np\">SALAH</span> 6. Kajian Turtle mendapati mereka dagang pada 2× risiko yang disyorkan.<span class=\"np\">BETUL</span> 7. Jerry Parker percaya strategi mean reversion berkesan.<span class=\"np\">SALAH</span> 8. Salem Abraham belajar mula-mula dari Jerry Parker, bukan Dennis.<span class=\"np\">BETUL</span> 9. Jika formula unit beri 0.2 kontrak FCPO, bundarkan kepada 1 lot.<span class=\"np\">SALAH</span></div>"}, {"n": 44, "k": "Penutup", "t": "Peraturan boleh diajar dalam dua minggu. Disiplin perlu dibina seumur hidup.", "h": "<div class=\"nc\"><h3>Esok</h3><p>Tulis pelan trading 1 muka surat.</p></div><div class=\"nc\"><h3>Minggu ini</h3><p>Mula backtest &amp; rutin harian 15 minit.</p></div><div class=\"nc\"><h3>90 hari</h3><p>Paper trade dengan disiplin ≥ 95% sebelum live.</p></div><p><b>Penafian:</b> Bahan ini untuk tujuan pendidikan sahaja dan bukan nasihat pelaburan. Dagangan niaga hadapan melibatkan leverage dan risiko kerugian melebihi modal. Semua angka harga, N dan akaun ialah contoh andaian. Sumber: ringkasan <i>The Complete TurtleTrader</i> (Michael W. Covel); spesifikasi FCPO dari Bursa Malaysia / KGI.</p>"}], "2": [{"n": 1, "k": "Muka depan", "t": "Turtle × FCPO: Kajian Kes Januari – September 2026", "h": "<p>Sistem Turtle diuji pada data harian sebenar FCPO bulan ketiga — setiap isyarat, setiap stop, setiap rugi. Kemudian kita bina SOP yang menapis isyarat lemah.</p><span class=\"np\">173 hari dagangan</span><span class=\"np\">6 isyarat Sistem 1</span><span class=\"np\">SOP 8 langkah</span>"}, {"n": 2, "k": "Kandungan", "t": "Apa yang ada dalam siri 2", "h": "<div class=\"nc\"><span class=\"np\">BAHAGIAN A</span><h3>Data &amp; peta pasaran</h3><p>Dari mana data diambil, bagaimana kontrak disambung, dan 4 fasa FCPO tahun 2026.</p></div><div class=\"nc\"><span class=\"np\">BAHAGIAN B</span><h3>6 isyarat Sistem 1</h3><p>Setiap trade dibedah atas carta: entry, stop 2N, exit 10 hari, untung/rugi dalam RM.</p></div><div class=\"nc\"><span class=\"np\">BAHAGIAN C</span><h3>Kebenaran win rate</h3><p>9 penapis popular diuji. Mana yang naikkan win rate — dan mana yang sebenarnya merosakkan.</p></div><div class=\"nc nc-dark\"><span class=\"np\">BAHAGIAN D</span><h3>SOP Turtle-FCPO</h3><p>8 langkah, peraturan larangan entry, dan hasilnya pada carta yang sama.</p></div><div class=\"nc\"><span class=\"np\">BAHAGIAN E</span><h3>Alat kerja</h3><p>Senarai semak pra-entry, jadual harian, SOP rollover.</p></div><div class=\"nc\"><span class=\"np\">BAHAGIAN F</span><h3>Had kajian</h3><p>Apa yang data 9 bulan boleh dan tak boleh buktikan.</p></div>"}, {"n": 3, "k": "Bahagian A · Kaedah", "t": "Data yang digunakan", "h": "<div class=\"nc\"><h3>Sumber</h3><p>Laporan harian “Palm Oil Prices at Closing” (CPO futures, MDEX) dari blog agropost — open, high, low, harga akhir bagi setiap bulan kontrak. <b>2 Jan – 30 Sep 2026, 173 hari dagangan.</b></p></div><div class=\"nc\"><h3>Kontrak: bulan ketiga</h3><p>Setiap bulan kita guna kontrak penanda aras (bulan semasa + 3). Jan → Apr'26, Feb → Mei'26 … Sep → Dis'26. Roll pada hari dagangan pertama setiap bulan.</p></div><div class=\"nc nc-amber\"><h3>Hari yang tiada data</h3><p>Cuti umum dan beberapa hari tanpa laporan (cth. 2–3 Feb, 20 Feb, 8 Apr, 25 Ogo, 10–16 Sep). Carta melangkau hari tersebut.</p></div><div class=\"nc nc-dark\"><h3>Kenapa perlu “laraskan” harga?</h3><p>Bila roll, kontrak baru biasanya lebih mahal (contango). Cth. 1 Sep: Nov'26 = 4,971 tetapi Dis'26 = 5,070 → beza 99 mata. Itu <b>bukan</b> pergerakan pasaran.</p><p>Jadi paras breakout, N dan untung/rugi dikira atas siri yang dilaraskan (back-adjusted). Carta pula memaparkan <b>harga sebenar</b> kontrak yang didagang hari itu.</p></div><div class=\"ntw\"><table><tr><th>Roll</th><th>Beza (mata)</th><th>Roll</th><th>Beza</th></tr><tr><td>Feb → Mei'26</td><td>+1</td><td>Jun → Sep'26</td><td>+30</td></tr><tr><td>Mac → Jun'26</td><td>+5</td><td>Jul → Okt'26</td><td>+23</td></tr><tr><td>Apr → Jul'26</td><td>+4</td><td>Ogo → Nov'26</td><td>+33</td></tr><tr><td>Mei → Ogo'26</td><td>+17</td><td>Sep → Dis'26</td><td><b>+99</b></td></tr></table></div>"}, {"n": 4, "k": "Bahagian A · Peta Pasaran", "t": "FCPO Jan–Sep 2026 dengan saluran 20 hari & isyarat Sistem 1", "h": "<div class=\"nchart\"><img alt=\"Carta full\" class=\"nimg\" loading=\"lazy\" src=\"notes/full.webp\"/></div><div class=\"nc\"><p><b>Jan–Feb · Sideways</b><br/>3,980–4,340. Tiada breakout bersih.</p></div><div class=\"nc nc-grn\"><p><b>Mac · Rali kuat</b><br/>Jun'26 dari ~4,150 → 4,830 (+16%).</p></div><div class=\"nc nc-amber\"><p><b>Apr–Jul · Julat berombak</b><br/>4,400–4,800. Kebanyakan rugi berlaku di sini.</p></div><div class=\"nc nc-red\"><p><b>Ogo–Sep · Naik &amp; berpusing</b><br/>Puncak ~5,150 (8 Sep) → 4,612 (30 Sep).</p></div>"}, {"n": 5, "k": "Bahagian A · Volatiliti N", "t": "N sebenar FCPO 2026 — dan apa maksudnya untuk modal anda", "h": "<div class=\"nchart\"><img alt=\"Carta n\" class=\"nimg\" loading=\"lazy\" src=\"notes/n.webp\"/></div><div class=\"ntw\"><table><tr><th>N (mata)</th><th>1N sekontrak</th><th>Modal min. untuk 1 kontrak @ risiko 1%</th></tr><tr><td>65 (akhir Jan, paling tenang)</td><td>RM1,625</td><td><b>RM162,500</b></td></tr><tr><td>80 (akhir Sep)</td><td>RM2,000</td><td><b>RM200,000</b></td></tr><tr><td>114 (Apr, paling ganas)</td><td>RM2,850</td><td><b>RM285,000</b></td></tr></table></div><div class=\"nc nc-amber\"><p><b>Formula:</b> Modal minimum = N × RM25 ÷ 1% = <b>N × RM2,500</b>.</p></div><div class=\"nc nc-red\"><h3>Realiti untuk akaun kecil</h3><p>Akaun RM50,000 yang buka 1 kontrak bila N = 80 sebenarnya mempertaruhkan <b>4% sekali N</b>, dan <b>8% jika kena stop 2N</b>. Tiga kali stop berturut-turut = akaun hilang ~24%. SOP mewajibkan anda kira ini dulu.</p></div>"}, {"n": 6, "k": "Bahagian B · Semua Isyarat", "t": "6 isyarat Sistem 1 (breakout 20 hari, exit 10 hari, stop 2N)", "h": "<div class=\"ntw\"><table><tr><th>#</th><th>Arah</th><th>Tarikh entry</th><th>Kontrak</th><th>Entry</th><th>N</th><th>Stop 2N</th><th>Tarikh exit</th><th>Exit</th><th>Sebab</th><th>Mata*</th><th>RM / kontrak</th></tr><tr><td>1</td><td><span class=\"np\">LONG</span></td><td>6 Mac</td><td>Jun'26</td><td>4,347</td><td>75</td><td>4,197</td><td>13 Apr</td><td>4,547 (Jul)</td><td>Exit 10 hari</td><td>+196</td><td>+4,900</td></tr><tr><td>2</td><td><span class=\"np\">SHORT</span></td><td>14 Apr</td><td>Jul'26</td><td>4,471</td><td>112</td><td>4,695</td><td>5 Mei</td><td>4,657 (Ogo)</td><td>Exit 10 hari</td><td>−169</td><td>−4,225</td></tr><tr><td>3</td><td><span class=\"np\">SHORT</span></td><td>12 Mei</td><td>Ogo'26</td><td>4,450</td><td>97</td><td>4,644</td><td>20 Mei</td><td>4,644</td><td>Stop 2N</td><td>−194</td><td>−4,850</td></tr><tr><td>4</td><td><span class=\"np\">SHORT</span></td><td>3 Jul</td><td>Okt'26</td><td>4,486</td><td>82</td><td>4,651</td><td>9 Jul</td><td>4,651</td><td>Stop 2N</td><td>−165</td><td>−4,125</td></tr><tr><td>5</td><td><span class=\"np\">LONG</span></td><td>23 Jul</td><td>Okt'26</td><td>4,662</td><td>73</td><td>4,516</td><td>18 Sep</td><td>4,898 (Dis)</td><td>Exit 10 hari</td><td>+104</td><td>+2,600</td></tr><tr><td>6</td><td><span class=\"np\">SHORT</span></td><td>21 Sep</td><td>Dis'26</td><td>4,848</td><td>80</td><td>5,008</td><td>masih terbuka</td><td>4,612 (30 Sep)</td><td>Belum exit</td><td>+236</td><td>+5,900</td></tr><tr><td colspan=\"10\"><b>Jumlah (1 kontrak, termasuk posisi terbuka)</b></td><td><b>+8</b></td><td>≈ +RM200</td></tr></table></div><div class=\"nc\"><p>* Mata dikira atas siri dilaraskan — sudah termasuk kos roll. Cth. trade #5: harga sebenar naik 4,662 → 4,898 (+236), tetapi 132 mata daripadanya ialah beza harga ketika roll ke Nov &amp; Dis. Untung sebenar hanya +104.</p></div><div class=\"nc nc-amber\"><p><b>Ringkasnya:</b> 3 menang, 3 kalah (win rate 50%). Hampir pulang modal selepas 9 bulan — 3 kerugian dalam pasaran berombak memakan hampir semua untung trend Mac.</p></div>"}, {"n": 7, "k": "Bahagian B · Kes #1 · Menang", "t": "Rali Mac: contoh trend yang Turtle tunggu-tunggu", "h": "<div class=\"nchart\"><img alt=\"Carta z1\" class=\"nimg\" loading=\"lazy\" src=\"notes/z1.webp\"/></div><div class=\"nrow\"><b class=\"nstep\">1</b><h3>Isyarat</h3><p>6 Mac: harga pecah paras tertinggi 20 hari (~4,346). Beli Jun'26 pada <b>4,347</b>.</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><h3>Risiko</h3><p>N = 75 → stop 2N = <b>4,197</b> (risiko 150 mata = RM3,750 sekontrak).</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><h3>Ujian kesabaran</h3><p>9 Mac: lonjakan liar ke ~4,800 lalu jatuh balik. Turtle <b>tidak ambil untung</b> — tiada peraturan exit tercetus.</p></div><div class=\"nrow\"><b class=\"nstep\">4</b><h3>Exit</h3><p>13 Apr: harga pecah paras terendah 10 hari → keluar <b>4,547 (Jul'26)</b>. Untung +196 mata = <b>+RM4,900</b>.</p></div><div class=\"nc nc-grn\"><p><b>Pengajaran:</b> exit 10 hari memulangkan ~250 mata dari puncak. Itu “harga” untuk tidak meneka puncak.</p></div>"}, {"n": 8, "k": "Bahagian B · Kes #2 & #3 · Kalah", "t": "April–Mei: dua short dalam pasaran yang tidak pergi ke mana-mana", "h": "<div class=\"nchart\"><img alt=\"Carta z4\" class=\"nimg\" loading=\"lazy\" src=\"notes/z4.webp\"/></div><div class=\"nc nc-red\"><h3>Kes #2 · Short 14 Apr</h3><p>Entry 4,471 bila pecah paras terendah 20 hari. Harga terus berlegar, kemudian naik. Exit 10 hari pada 5 Mei → <b>−RM4,225</b>. Perhatikan N ketika itu 112 — paling tinggi tahun ini.</p></div><div class=\"nc nc-red\"><h3>Kes #3 · Short 12 Mei</h3><p>Entry 4,450 bila pecah paras terendah 20 hari. Harga melantun dan kena stop 2N pada 20 Mei → <b>−RM4,850</b>.</p></div><div class=\"nc nc-amber\"><p><b>Corak:</b> kedua-dua short masuk ketika harga penutupan semalam masih <b>di atas garis tengah 55 hari</b> — trend jangka panjang belum turun. Ini idea untuk Penapis 1 dalam SOP. (Penapis ini menolak #2; tetapi 2 hari kemudian isyarat short yang sah tetap muncul dan rugi — tiada penapis yang sempurna.)</p></div>"}, {"n": 9, "k": "Bahagian B · Kes #4 · Kalah", "t": "Julai: breakout palsu yang terbalik dalam 4 hari", "h": "<div class=\"nchart\"><img alt=\"Carta z2\" class=\"nimg\" loading=\"lazy\" src=\"notes/z2.webp\"/></div><div class=\"nrow\"><b class=\"nstep\">1</b><h3>Isyarat</h3><p>3 Jul: harga mencecah bawah paras terendah 20 hari <b>secara intraday</b>. Short Okt'26 pada 4,486.</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><h3>Masalah</h3><p>Hari itu harga hanya “mencucuk” paras — tiada penutupan yang kukuh di bawahnya. Esoknya pasaran terus pulih.</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><h3>Keputusan</h3><p>9 Jul: kena stop 2N pada 4,651 → <b>−RM4,125</b>.</p></div><div class=\"nc nc-amber\"><p><b>Idea Penapis 2:</b> tunggu harga <b>tutup</b> di luar paras breakout, kemudian masuk pada pembukaan esoknya. Kurang isyarat palsu — tetapi kadang-kadang harga masuk lebih buruk.</p></div>"}, {"n": 10, "k": "Bahagian B · Kes #5 & #6 · Menang", "t": "Ogos–Sep: tunggang trend naik, kemudian tangkap pusingan", "h": "<div class=\"nchart\"><img alt=\"Carta z3\" class=\"nimg\" loading=\"lazy\" src=\"notes/z3.webp\"/></div><div class=\"nc nc-grn\"><h3>Kes #5 · Long 23 Jul → 18 Sep</h3><p>Ditahan hampir 2 bulan, merentasi 2 roll. Harga sebenar 4,662 → 4,898, tetapi untung sebenar cuma <b>+104 mata (+RM2,600)</b> kerana contango semasa roll.</p></div><div class=\"nc nc-grn\"><h3>Kes #6 · Short 21 Sep (terbuka)</h3><p>Selepas exit long, harga pecah paras terendah 20 hari. Pada 30 Sep: 4,612 → <b>+RM5,900</b> belum direalisasi. Stop sudah boleh dihadkan oleh exit 10 hari.</p></div><div class=\"nc nc-dark\"><p><b>Pengajaran roll:</b> jangan kira untung dengan menolak harga dua kontrak berbeza. Catat setiap roll dalam jurnal: harga tutup kontrak lama dan harga buka kontrak baru.</p></div>"}, {"n": 11, "k": "Bahagian B · Keputusan Sistem Asas", "t": "Apa yang 9 bulan ini ajar kita", "h": "<div class=\"nc\"><p class=\"nn\">6</p><p>isyarat dalam 9 bulan<br/>(≈ 1 setiap 6 minggu)</p></div><div class=\"nc\"><p class=\"nn\">50%</p><p>win rate<br/>(3 menang, 3 kalah)</p></div><div class=\"nc\"><p class=\"nn\">+RM4,467</p><p>purata trade menang</p></div><div class=\"nc\"><p class=\"nn\">−RM4,400</p><p>purata trade kalah</p></div><div class=\"nc nc-dark\"><h3>Expectancy sebenar</h3><p>(0.5 × 4,467) − (0.5 × 4,400) ≈ <b>+RM33 setiap trade</b></p><p>Hampir sifar. Tiada trend besar kedua selepas Mac untuk menampung kerugian dalam pasaran berombak.</p></div><div class=\"nc\"><h3>Tiga kesimpulan jujur</h3><ul><li>Trend following <b>bergantung pada beberapa trend besar</b>. Tahun berombak = tahun hampir kosong.</li><li>Kerugian terbesar datang dari <b>isyarat melawan trend jangka panjang</b> dan <b>breakout intraday yang tidak ditutup</b>.</li><li>Kos roll (contango) <b>menghakis untung long</b> yang dipegang lama.</li></ul></div>"}, {"n": 12, "k": "Bahagian C & D", "t": "Boleh tak kita naikkan win rate?", "h": "<p class=\"nn\">SOP</p><p>Kita uji 9 versi peraturan pada data yang sama — kemudian bina SOP daripada yang benar-benar membantu.</p>"}, {"n": 13, "k": "Bahagian C · Kebenaran Win Rate", "t": "9 penapis diuji pada data Jan–Sep 2026", "h": "<p>Win rate</p><div class=\"nchart\"><img alt=\"Carta bars_wr\" class=\"nimg\" loading=\"lazy\" src=\"notes/bars_wr.webp\"/></div><p>Untung / rugi bersih</p><div class=\"nchart\"><img alt=\"Carta bars_rm\" class=\"nimg\" loading=\"lazy\" src=\"notes/bars_rm.webp\"/></div><div class=\"nc nc-red\"><p><b>Helah popular yang gagal:</b> stop pulang modal @1N dan ambil separuh untung @2N <b>menurunkan</b> keputusan — trend dipotong awal.</p></div><div class=\"nc nc-amber\"><p><b>Satu penapis sahaja tak cukup.</b> Sah harga tutup sahaja, atau trend SMA50 sahaja — kedua-duanya lebih teruk dari asas.</p></div><div class=\"nc nc-pur\"><p><b>Gabungan yang membantu:</b> sah harga tutup + garis tengah 55 hari → win rate 50% → <b>67%</b>, untung +RM217 → <b>+RM1,485</b>.</p></div>"}, {"n": 14, "k": "Bahagian D · SOP Turtle-FCPO", "t": "8 langkah, setiap hari, tanpa kecuali", "h": "<div class=\"nrow\"><b class=\"nstep\">1</b><h3>Kemas kini data</h3><p>Selepas 6 ptg. Kontrak bulan ketiga.</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><h3>Kira N &amp; saiz</h3><p>Unit = 1% ekuiti ÷ (N×25). Bundar ke bawah.</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><h3>Tanda paras</h3><p>Tinggi/rendah 20 hari, exit 10 hari, garis tengah 55 hari.</p></div><div class=\"nrow\"><b class=\"nstep\">4</b><h3>Penapis trend</h3><p>Long hanya di atas garis 55. Short hanya di bawah.</p></div><div class=\"nrow\"><b class=\"nstep\">5</b><h3>Sah harga tutup</h3><p>Isyarat sah hanya jika harga <b>tutup</b> di luar paras 20 hari.</p></div><div class=\"nrow\"><b class=\"nstep\">6</b><h3>Entry &amp; stop</h3><p>Masuk pada pembukaan esok. Stop 2N terus dipasang.</p></div><div class=\"nrow\"><b class=\"nstep\">7</b><h3>Urus posisi</h3><p>Exit 10 hari bergerak. Roll hari dagangan pertama bulan.</p></div><div class=\"nrow\"><b class=\"nstep\">8</b><h3>Exit &amp; jurnal</h3><p>Keluar bila exit/stop tercetus. Catat semua.</p></div>"}, {"n": 15, "k": "Bahagian D · SOP Langkah 1–4", "t": "Persediaan: sebelum isyarat muncul", "h": "<div class=\"nrow\"><b class=\"nstep\">1</b><h3>Kemas kini data (selepas 6:00 ptg)</h3><p>Ambil OHLC harian kontrak bulan ketiga. Hari pertama bulan baru → tukar ke kontrak baru dan catat beza harga roll.</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><h3>Kira N dan saiz unit</h3><p>N = ATR(20). Unit = (1% × ekuiti semasa) ÷ (N × RM25). <b>Jika &lt; 1 → tiada dagangan.</b> Jika akaun dalam drawdown 10%, kira guna ekuiti 20% lebih kecil.</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><h3>Tanda 5 paras atas carta</h3><p>(a) Tertinggi 20 hari, (b) terendah 20 hari, (c) tertinggi 10 hari, (d) terendah 10 hari, (e) garis tengah 55 hari = (tertinggi 55 + terendah 55) ÷ 2.</p></div><div class=\"nrow\"><b class=\"nstep\">4</b><h3>Penapis trend (garis tengah 55 hari)</h3><p>Harga tutup <b>di atas</b> garis → hanya cari LONG. Harga tutup <b>di bawah</b> → hanya cari SHORT. Kes #2 (short 14 Apr) tertapis oleh peraturan ini.</p></div><div class=\"nc nc-amber\"><p><b>Kenapa garis tengah 55 hari, bukan SMA50?</b> Dalam ujian kita, SMA50 sendirian menurunkan untung (−RM6,283). Garis tengah 55 hari menggunakan paras Sistem 2 Turtle sendiri — konsisten dengan logik breakout.</p></div>"}, {"n": 16, "k": "Bahagian D · SOP Langkah 5–8", "t": "Pelaksanaan: dari isyarat hingga jurnal", "h": "<div class=\"nrow\"><b class=\"nstep\">5</b><h3>Sah dengan harga tutup</h3><p>Long sah hanya jika harga <b>tutup</b> &gt; tertinggi 20 hari sebelumnya (short: tutup &lt; terendah 20 hari). Cucukan intraday diabaikan — Kes #4 akan tertapis.</p></div><div class=\"nrow\"><b class=\"nstep\">6</b><h3>Entry &amp; stop serentak</h3><p>Masuk pada <b>pembukaan sesi pagi (10:30)</b> esoknya. Pada saat yang sama pasang stop 2N. Tiada stop = tiada trade.</p></div><div class=\"nrow\"><b class=\"nstep\">7</b><h3>Urus posisi setiap petang</h3><p>Stop berkesan = paras <b>lebih ketat</b> antara stop 2N dan exit 10 hari. Hari dagangan pertama setiap bulan: roll ke kontrak bulan ketiga baru, kekalkan jarak stop dalam mata.</p></div><div class=\"nrow\"><b class=\"nstep\">8</b><h3>Exit &amp; jurnal</h3><p>Exit bila stop tercetus — tanpa runding. Catat: tarikh, kontrak, N, entry, stop, exit, sebab, RM, emosi, “ikut SOP? Ya/Tidak”.</p></div><div class=\"nc nc-dark\"><p><b>Kos penapis:</b> masuk pada pembukaan esok kadang-kadang memberi harga lebih buruk berbanding entry intraday (cth. Kes #5 SOP masuk 4,721 berbanding 4,662). Itu harga yang dibayar untuk mengelak isyarat palsu.</p></div>"}, {"n": 17, "k": "Bahagian D · Peraturan Larangan", "t": "7 keadaan “TIDAK BOLEH ENTRY”", "h": "<div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Saiz unit kurang dari 1 kontrak</h3><p>Modal tidak cukup untuk risiko 1% pada N semasa.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Melawan garis tengah 55 hari</h3><p>Long di bawah garis, atau short di atas garis.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Breakout tidak ditutup</h3><p>Harga hanya mencucuk paras secara intraday.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Hari laporan MPOB (~10hb)</h3><p>Tunggu esok. Dalam data ini kesannya kecil (+RM55), tetapi ia mengurangkan risiko gap.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Pasaran kena had harga (limit)</h3><p>Stop mungkin tidak terisi. Tunggu pasaran dibuka normal.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Kontrak bulan spot / penghantaran</h3><p>Penghantaran fizikal. Hanya dagang bulan ketiga.</p></div><div class=\"nrow\"><b class=\"nstep\">✕</b><h3>Stop belum ditentukan</h3><p>Tiada nombor stop bertulis = tiada order.</p></div><div class=\"nc nc-pur\"><p><b>Ingat:</b> larangan ini <b>bukan</b> untuk elak rugi berturut-turut. Turtle tak skip isyarat sebab takut — hanya sebab peraturan bertulis.</p></div>"}, {"n": 18, "k": "Bahagian D · SOP Atas Carta", "t": "Data yang sama, SOP yang sama — 3 isyarat sahaja", "h": "<div class=\"nchart\"><img alt=\"Carta full_sop\" class=\"nimg\" loading=\"lazy\" src=\"notes/full_sop.webp\"/></div><div class=\"ntw\"><table><tr><th>#</th><th>Arah</th><th>Isyarat sah (tutup)</th><th>Entry (buka esok)</th><th>Stop 2N</th><th>Exit</th><th>RM / kontrak</th></tr><tr><td>1</td><td><span class=\"np\">SHORT</span></td><td>13 Mei, tutup di bawah garis 55</td><td>14 Mei · 4,469 (Ogo)</td><td>4,661</td><td>20 Mei · stop 2N</td><td>−4,800</td></tr><tr><td>2</td><td><span class=\"np\">LONG</span></td><td>23 Jul, tutup di atas garis 55</td><td>24 Jul · 4,721 (Okt)</td><td>4,572</td><td>18 Sep · exit 10 hari · 4,898 (Dis)</td><td>+1,125</td></tr><tr><td>3</td><td><span class=\"np\">SHORT</span></td><td>22 Sep, tutup di bawah garis 55</td><td>23 Sep · 4,818 (Dis)</td><td>4,979</td><td>terbuka · 4,612 pada 30 Sep</td><td>+5,150</td></tr></table></div>"}, {"n": 19, "k": "Bahagian D · Asas vs SOP", "t": "Lebih sedikit trade, kurang drawdown, hasil lebih baik", "h": "<div class=\"nchart\"><img alt=\"Carta equity\" class=\"nimg\" loading=\"lazy\" src=\"notes/equity.webp\"/></div><div class=\"ntw\"><table><tr><th></th><th>Sistem asas</th><th>SOP</th></tr><tr><td>Bilangan trade</td><td>6</td><td>3</td></tr><tr><td>Win rate</td><td>50%</td><td><b>67%</b></td></tr><tr><td>Untung bersih (1 kontrak)</td><td>+RM217</td><td>+RM1,485</td></tr><tr><td>Drawdown terburuk</td><td>≈ −RM13,200</td><td>≈ −RM4,800</td></tr><tr><td>Kerugian berturut-turut</td><td>3</td><td>1</td></tr></table></div><div class=\"nc nc-amber\"><p><b>Faedah terbesar bukan win rate</b> — tetapi drawdown hampir 3× lebih kecil. Itu yang menentukan sama ada trader baharu mampu bertahan dan terus ikut sistem.</p></div><div class=\"nc nc-red\"><p><b>Awas:</b> SOP juga terlepas trend Mac (+RM4,900) kerana garis 55 hari belum terbentuk. Penapis sentiasa ada kos.</p></div>"}, {"n": 20, "k": "Bahagian E · Alat Kerja", "t": "Senarai semak pra-entry (cetak & tampal)", "h": "<ul><li>Kontrak = bulan ketiga (bukan bulan spot)</li><li>N hari ini dikira: ______ mata = RM______</li><li>Saiz unit = 1% ekuiti ÷ (N×25) ≥ 1 kontrak</li><li>Ekuiti dalam drawdown? Jika ≥10%, saiz dikurangkan</li><li>Harga <b>tutup</b> di luar paras 20 hari</li></ul><ul><li>Arah selari dengan garis tengah 55 hari</li><li>Bukan hari laporan MPOB / bukan hari limit</li><li>Stop 2N bertulis: ______</li><li>Paras exit 10 hari bertulis: ______</li><li>Saya sanggup terima rugi RM______ tanpa emosi</li></ul><div class=\"nc nc-dark\"><p><b>Semua 10 kotak bertanda?</b> → Hantar order untuk pembukaan esok. <b>Satu kotak kosong?</b> → Tiada dagangan. Tiada pengecualian.</p></div>"}, {"n": 21, "k": "Bahagian E · Jadual SOP", "t": "Bila buat apa — ikut waktu dagangan FCPO", "h": "<div class=\"ntw\"><table><tr><th>Masa</th><th>Tugasan</th><th>Output</th></tr><tr><td><b>6:00 – 6:30 ptg</b> (selepas tutup)</td><td>Langkah 1–5: data, N, saiz, paras, penapis trend &amp; sah harga tutup</td><td>Senarai semak lengkap / “tiada isyarat”</td></tr><tr><td><b>9:00 – 11:30 mlm</b> (sesi T+1)</td><td>Tidak buat keputusan baru. Pantau sahaja jika ada posisi; stop sudah dipasang</td><td>—</td></tr><tr><td><b>10:30 pg</b> (buka sesi pagi)</td><td>Langkah 6: entry pada harga buka + pasang stop 2N serentak</td><td>Pengesahan order &amp; stop</td></tr><tr><td><b>Setiap petang</b></td><td>Langkah 7: kemas kini exit 10 hari, gerakkan stop ke paras lebih ketat</td><td>Stop baru dalam platform</td></tr><tr><td><b>Hari dagangan pertama bulan</b></td><td>Roll ke kontrak bulan ketiga baru; catat harga lama &amp; baru</td><td>Baris roll dalam jurnal</td></tr><tr><td><b>Sekitar 10hb</b></td><td>Laporan MPOB — tiada entry baru hari itu</td><td>—</td></tr><tr><td><b>Jumaat</b></td><td>Semakan mingguan: % ikut SOP, drawdown, ekuiti untuk minggu depan</td><td>Skor disiplin (sasaran 100%)</td></tr></table></div>"}, {"n": 22, "k": "Bahagian E · SOP Rollover", "t": "Cara roll posisi tanpa kacau sistem", "h": "<div class=\"nrow\"><b class=\"nstep\">1</b><h3>Bila?</h3><p>Hari dagangan pertama setiap bulan — tukar ke kontrak (bulan semasa + 3).</p></div><div class=\"nrow\"><b class=\"nstep\">2</b><h3>Bagaimana?</h3><p>Tutup kontrak lama dan buka kontrak baru dengan bilangan lot yang sama, pada hari yang sama.</p></div><div class=\"nrow\"><b class=\"nstep\">3</b><h3>Stop?</h3><p>Kekalkan <b>jarak dalam mata</b>. Cth. stop 120 mata di bawah harga lama → 120 mata di bawah harga baru.</p></div><div class=\"nrow\"><b class=\"nstep\">4</b><h3>Catat</h3><p>Harga keluar kontrak lama + harga masuk kontrak baru. Untung/rugi = jumlah setiap “kaki”, bukan beza dua kontrak.</p></div><div class=\"nc\"><h3>Contoh sebenar · 1 Sep 2026</h3><div class=\"ntw\"><table><tr><td>Tutup long Nov'26</td><td>4,971</td></tr><tr><td>Buka long Dis'26</td><td>5,070</td></tr><tr><td>Beza (bukan untung!)</td><td><b>99 mata</b></td></tr><tr><td>Stop lama (Nov) 4,7xx → stop baru</td><td>+99 mata</td></tr></table></div></div><div class=\"nc nc-red\"><p><b>Contango 2026 besar di Ogos–Sep.</b> Long yang dipegang lama membayar beza ini secara tidak langsung. Short pula mendapat manfaat.</p></div>"}, {"n": 23, "k": "Bahagian F · Had Kajian", "t": "Apa yang kajian ini TIDAK buktikan", "h": "<div class=\"nc nc-red\"><h3>Sampel terlalu kecil</h3><p>6 trade (asas) dan 3 trade (SOP) bukan bukti statistik. Win rate 67% atas 3 trade boleh jadi kebetulan. Satu trade terakhir masih terbuka.</p></div><div class=\"nc nc-red\"><h3>Risiko “curve fitting”</h3><p>Penapis dipilih <b>selepas</b> melihat data yang sama. Prestasi masa depan hampir pasti lebih rendah.</p></div><div class=\"nc nc-amber\"><h3>Kualiti data</h3><p>Data dari laporan blog harian; beberapa hari tiada laporan dan ada nilai OHLC yang tidak konsisten (dibetulkan supaya high ≥ harga, low ≤ harga).</p></div><div class=\"nc nc-amber\"><h3>Kos tidak dikira</h3><p>Komisen broker, slippage dan kos roll sebenar belum ditolak.</p></div><div class=\"nc nc-dark\"><h3>Langkah seterusnya untuk setiap peserta</h3><ul><li>Ulang ujian yang sama pada <b>3–5 tahun data</b> (minimum 30 trade) sebelum guna wang sebenar.</li><li>Bandingkan sistem asas vs SOP: pilih yang <b>drawdown</b> paling boleh anda tanggung, bukan yang win rate paling tinggi.</li><li>Paper trade SOP sekurang-kurangnya 3 bulan dengan skor disiplin ≥ 95%.</li></ul></div>"}, {"n": 24, "k": "Penutup", "t": "Win rate tinggi bukan matlamat. Kekal dalam permainan sehingga trend besar datang — itu matlamatnya.", "h": "<p>SOP ini menapis isyarat lemah supaya anda rugi lebih sedikit dalam pasaran berombak — dan masih berada di pasaran bila FCPO bergerak jauh.</p><p><b>Penafian:</b> Bahan pendidikan sahaja, bukan nasihat pelaburan. Prestasi lalu tidak menjamin prestasi masa depan. Niaga hadapan melibatkan leverage dan risiko kerugian melebihi modal. <b>Sumber data:</b> laporan harian “Palm Oil Prices at Closing” (CPO futures MDEX), agropost.wordpress.com, Jan–Sep 2026. Kiraan Turtle, penyelarasan roll dan ujian penapis dibuat oleh penyedia bahan. Kaedah: <i>The Complete TurtleTrader</i> (Michael W. Covel).</p>"}], "3": [{"n": 1, "k": "Fasa 1 · Minda & Modal", "t": "Faham matematik trend following", "h": "<p>Turtle tidak menang kerana kerap betul. Trend follower biasanya kalah lebih kerap — tetapi untung besar menutup rugi kecil. Win rate 35% masih boleh untung jika purata untung 3× purata rugi.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Kira expectancy: (% menang × purata untung) − (% kalah × purata rugi)</li><li>Terima win rate 35–50% sebagai normal</li><li>Berhenti mencari sistem “90% menang”</li></ul></div><div class=\"nchart\"><img src=\"notes/payoff.webp\" alt=\"Expectancy setiap trade ikut win rate dan nisbah untung:rugi (rugi purata RM1,500).\" loading=\"lazy\" class=\"nimg\"></div><p><small>Expectancy setiap trade ikut win rate dan nisbah untung:rugi (rugi purata RM1,500).</small></p><p><small>Rujukan: Siri 1 · slaid 16 · Siri 2 · slaid 11</small></p>"}, {"n": 2, "k": "Fasa 1 · Minda & Modal", "t": "Kenali nilai setiap pergerakan FCPO", "h": "<p>Satu kontrak = 25 tan. Setiap 1 mata = RM25. Pergerakan harian biasa (1N) bernilai ~RM2,000 sekontrak, dan had harga 10% boleh mencecah ~RM11,500. Inilah sebab saiz posisi mesti dikira, bukan diteka.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Hafal: 1 mata = RM25 sekontrak</li><li>Semak margin semasa dengan broker anda</li><li>Ingat: FCPO diselesaikan secara penghantaran fizikal</li></ul></div><div class=\"nchart\"><img src=\"notes/tickval.webp\" alt=\"Nilai untung/rugi bagi 1 kontrak FCPO (harga ~RM4,600, N = 80).\" loading=\"lazy\" class=\"nimg\"></div><p><small>Nilai untung/rugi bagi 1 kontrak FCPO (harga ~RM4,600, N = 80).</small></p><p><small>Rujukan: Siri 1 · slaid 19, 37</small></p>"}, {"n": 3, "k": "Fasa 1 · Minda & Modal", "t": "Semak modal anda berbanding N", "h": "<p>Untuk risiko 1%, modal minimum bagi satu kontrak = N × RM2,500. Pada N 2026 (65–114 mata), itu bersamaan RM162k hingga RM285k. Akaun kecil yang paksa 1 lot sebenarnya mempertaruhkan 4–8% setiap trade.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Kira N hari ini dan modal minimum anda</li><li>Jika kiraan beri < 1 kontrak → jangan paksa</li><li>Pilihan: paper trade, kumpul modal, atau akaun prop</li></ul></div><div class=\"nchart\"><img src=\"notes/capital.webp\" alt=\"Modal minimum untuk 1 kontrak FCPO pada risiko 1% mengikut N.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Modal minimum untuk 1 kontrak FCPO pada risiko 1% mengikut N.</small></p><p><small>Rujukan: Siri 1 · slaid 20 · Siri 2 · slaid 5</small></p>"}, {"n": 4, "k": "Fasa 1 · Minda & Modal", "t": "Kunci risiko 1% setiap unit", "h": "<p>Kerugian berturut-turut pasti berlaku. Pada 1% setiap trade, 10 kekalahan berturut-turut tinggalkan 90% akaun. Pada 8%, tinggal 43% — dan anda perlu untung 130% untuk pulih.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Tulis had rugi per trade dalam RM, bukan dalam lot</li><li>Stop 2N = ~2% akaun bagi 1 unit</li><li>Bundarkan saiz ke bawah, sentiasa</li></ul></div><div class=\"nchart\"><img src=\"notes/ruin.webp\" alt=\"Baki akaun selepas kekalahan berturut-turut mengikut % risiko setiap trade.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Baki akaun selepas kekalahan berturut-turut mengikut % risiko setiap trade.</small></p><p><small>Rujukan: Siri 1 · slaid 20–21</small></p>"}, {"n": 5, "k": "Fasa 1 · Minda & Modal", "t": "Tulis pelan trading 1 muka surat", "h": "<p>Sistem lengkap = 6 jawapan bertulis. Bila semua sudah ditulis, tiada analisis lain diperlukan — keputusan semasa pasaran dibuka hanyalah melaksanakan, bukan berfikir.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Isi 6 kotak di sebelah sebelum trade pertama</li><li>Cetak dan letak di sebelah skrin</li><li>Kemas kini hanya pada hujung minggu, bukan semasa pasaran dibuka</li></ul></div><ul><li><b>Pasaran:</b> FCPO kontrak bulan ketiga</li><li><b>Saiz posisi:</b> 1% ekuiti ÷ (N × RM25), bundar ke bawah</li><li><b>Entry:</b> harga tutup melepasi paras 20 hari + selari garis 55</li><li><b>Stop loss:</b> 2N dari harga entry</li><li><b>Exit:</b> pecah paras berlawanan 10 hari</li><li><b>Taktik:</b> kurangkan saiz bila drawdown 10%; roll awal bulan</li></ul><p><small>Rujukan: Siri 1 · slaid 24</small></p>"}, {"n": 6, "k": "Fasa 2 · Sistem & Carta", "t": "Dagang hanya kontrak bulan ketiga", "h": "<p>Kontrak bulan ketiga ialah penanda aras paling aktif. Bulan spot berisiko penghantaran fizikal. Roll ke kontrak baru pada hari dagangan pertama setiap bulan.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Set carta harian kontrak (bulan semasa + 3)</li><li>Roll pada hari dagangan pertama bulan</li><li>Jangan sekali-kali pegang posisi ke bulan penghantaran</li></ul></div><p><b>Peraturan: bulan semasa + 3.</b> Contoh Oktober 2026 → Januari 2027. Elak bulan spot (risiko penghantaran fizikal).</p><p><small>Rujukan: Siri 2 · slaid 3, 22</small></p>"}, {"n": 7, "k": "Fasa 2 · Sistem & Carta", "t": "Pasang saluran breakout pada carta harian", "h": "<p>Turtle beli bila harga pecah paras tertinggi 20 hari dan short bila pecah paras terendah 20 hari. Exit bila harga pecah arah berlawanan 10 hari. Garis tengah 55 hari menunjukkan arah trend besar.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Plot Donchian 20 hari & 10 hari</li><li>Tambah garis tengah 55 hari = (tinggi 55 + rendah 55) ÷ 2</li><li>Tambah ATR(20) sebagai N</li></ul></div><div class=\"nchart\"><img src=\"notes/full.webp\" alt=\"FCPO bulan ketiga Jan–Sep 2026: saluran 20 hari dan 6 isyarat Sistem 1.\" loading=\"lazy\" class=\"nimg\"></div><p><small>FCPO bulan ketiga Jan–Sep 2026: saluran 20 hari dan 6 isyarat Sistem 1.</small></p><p><small>Rujukan: Siri 1 · slaid 17–18 · Siri 2 · slaid 15</small></p>"}, {"n": 8, "k": "Fasa 2 · Sistem & Carta", "t": "Kira N setiap petang", "h": "<p>N berubah setiap hari. Sepanjang 2026, N naik daripada 65 kepada 114 (April) kemudian turun ke 80. Saiz posisi yang sama pada N berbeza = risiko yang sangat berbeza.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Kemas kini N selepas pasaran tutup 6 petang</li><li>Kira semula saiz unit dengan ekuiti semasa</li><li>Catat N dalam jurnal setiap trade</li></ul></div><div class=\"nchart\"><img src=\"notes/n.webp\" alt=\"N (ATR 20 hari) FCPO bulan ketiga, Jan–Sep 2026.\" loading=\"lazy\" class=\"nimg\"></div><p><small>N (ATR 20 hari) FCPO bulan ketiga, Jan–Sep 2026.</small></p><p><small>Rujukan: Siri 2 · slaid 5</small></p>"}, {"n": 9, "k": "Fasa 2 · Sistem & Carta", "t": "Entry hanya bila harga TUTUP di luar paras", "h": "<p>Breakout intraday yang tidak ditutup kerap jadi perangkap. Kes #4 (3 Jul 2026): harga cucuk paras terendah 20 hari, kemudian berpusing dan kena stop 2N → −RM4,125.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Tunggu harga penutupan melepasi paras 20 hari</li><li>Masuk pada harga buka sesi pagi esoknya</li><li>Abaikan cucukan intraday — walaupun nampak meyakinkan</li></ul></div><div class=\"nchart\"><img src=\"notes/z2.webp\" alt=\"Kes #4: breakout palsu Julai 2026 yang kena stop 2N.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Kes #4: breakout palsu Julai 2026 yang kena stop 2N.</small></p><p><small>Rujukan: Siri 2 · slaid 9, 16</small></p>"}, {"n": 10, "k": "Fasa 2 · Sistem & Carta", "t": "Ikut arah garis tengah 55 hari", "h": "<p>Long hanya bila harga di atas garis tengah 55 hari; short hanya bila di bawah. Penapis ini menolak short rugi 14 Apr 2026 dan, bersama sah harga tutup, mengurangkan isyarat daripada 6 kepada 3.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Semak kedudukan harga vs garis tengah 55 setiap petang</li><li>Abaikan isyarat yang melawan arah garis</li><li>Terima kosnya: kadang-kadang terlepas trend awal (Mac 2026)</li></ul></div><div class=\"nchart\"><img src=\"notes/full_sop.webp\" alt=\"SOP pada data yang sama: garis tengah 55 hari (ungu) dan 3 isyarat yang lulus.\" loading=\"lazy\" class=\"nimg\"></div><p><small>SOP pada data yang sama: garis tengah 55 hari (ungu) dan 3 isyarat yang lulus.</small></p><p><small>Rujukan: Siri 2 · slaid 15, 18</small></p>"}, {"n": 11, "k": "Fasa 2 · Sistem & Carta", "t": "Pasang stop 2N serentak dengan entry", "h": "<p>Stop ditentukan sebelum masuk, dipasang serentak, dan hanya boleh bergerak ke arah untung. Kes #1: entry 4,347, N = 75 → stop 4,197 (risiko RM3,750 sekontrak).</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Tiada nombor stop bertulis = tiada order</li><li>Stop = entry − 2N (long) atau + 2N (short)</li><li>Jangan sekali-kali longgarkan stop</li></ul></div><div class=\"nchart\"><img src=\"notes/z1.webp\" alt=\"Kes #1 (Mac 2026): entry, stop 2N dan exit 10 hari pada carta.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Kes #1 (Mac 2026): entry, stop 2N dan exit 10 hari pada carta.</small></p><p><small>Rujukan: Siri 1 · slaid 21 · Siri 2 · slaid 7</small></p>"}, {"n": 12, "k": "Fasa 2 · Sistem & Carta", "t": "Biar trend berjalan — exit ikut paras 10 hari", "h": "<p>Turtle tidak meneka puncak. Kes #5 dipegang hampir dua bulan; kemudian exit 10 hari membawa ke short #6 yang untung +RM5,900 (belum direalisasi) apabila pasaran berpusing pada September.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Gerakkan stop ke paras lebih ketat antara 2N dan exit 10 hari</li><li>Jangan ambil untung awal kerana takut</li><li>Terima untung yang “dipulangkan” sebagai kos menunggu trend</li></ul></div><div class=\"nchart\"><img src=\"notes/z3.webp\" alt=\"Kes #5 & #6 (Jul–Sep 2026): tunggang trend naik, kemudian tangkap pusingan.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Kes #5 & #6 (Jul–Sep 2026): tunggang trend naik, kemudian tangkap pusingan.</small></p><p><small>Rujukan: Siri 1 · slaid 13 · Siri 2 · slaid 10</small></p>"}, {"n": 13, "k": "Fasa 2 · Sistem & Carta", "t": "Jangan tertipu helah “naikkan win rate”", "h": "<p>Dalam ujian 9 versi peraturan, stop pulang modal @1N dan ambil separuh untung @2N menurunkan keputusan. Hanya gabungan sah harga tutup + garis tengah 55 hari yang membantu.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Uji setiap penapis pada data sebelum guna</li><li>Nilai sistem dengan expectancy & drawdown, bukan win rate</li><li>Satu penapis sahaja jarang cukup</li></ul></div><div class=\"nchart\"><img src=\"notes/bars_rm.webp\" alt=\"Untung/rugi bersih 1 kontrak bagi 9 versi peraturan, data Jan–Sep 2026.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Untung/rugi bersih 1 kontrak bagi 9 versi peraturan, data Jan–Sep 2026.</small></p><p><small>Rujukan: Siri 2 · slaid 13</small></p>"}, {"n": 14, "k": "Fasa 2 · Sistem & Carta", "t": "Ambil kira kos roll (contango)", "h": "<p>Setiap kali roll, kontrak baru biasanya lebih mahal. Pada 1 Sep 2026, beza Nov→Dis ialah 99 mata (RM2,475). Kes #5: harga naik 236 mata, tetapi untung sebenar cuma 104 mata.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Catat harga tutup kontrak lama & buka kontrak baru</li><li>Kira untung ikut setiap “kaki”, bukan beza dua kontrak</li><li>Kekalkan jarak stop dalam mata selepas roll</li></ul></div><div class=\"nchart\"><img src=\"notes/roll.webp\" alt=\"Beza harga ketika roll ke kontrak bulan ketiga baru, Feb–Sep 2026.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Beza harga ketika roll ke kontrak bulan ketiga baru, Feb–Sep 2026.</small></p><p><small>Rujukan: Siri 2 · slaid 10, 22</small></p>"}, {"n": 15, "k": "Fasa 3 · Pelaksanaan Harian", "t": "Laksana rutin 15 minit selepas 6 petang", "h": "<p>Semua keputusan dibuat selepas pasaran tutup — tenang, tanpa tekanan harga bergerak. Order dihantar untuk pembukaan sesi pagi esok. Sesi malam T+1 bukan masa membuat keputusan baru.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>6:00 ptg: data → N → saiz → paras → penapis</li><li>10:30 pg: entry pada harga buka + stop serentak</li><li>Tutup carta; biar order bekerja</li></ul></div><div class=\"nchart\"><img src=\"notes/sessions.webp\" alt=\"Waktu dagangan FCPO dan bila rutin SOP dilakukan.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Waktu dagangan FCPO dan bila rutin SOP dilakukan.</small></p><p><small>Rujukan: Siri 1 · slaid 39 · Siri 2 · slaid 21</small></p>"}, {"n": 16, "k": "Fasa 3 · Pelaksanaan Harian", "t": "Guna senarai semak 10 kotak", "h": "<p>Satu kotak kosong = tiada dagangan. Senarai semak menukar disiplin daripada “kekuatan mental” kepada prosedur yang boleh diulang setiap hari.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Cetak senarai semak dan isi untuk setiap isyarat</li><li>Simpan senarai yang sudah diisi bersama jurnal</li><li>Semak semula setiap Jumaat</li></ul></div><ul><li>Kontrak = bulan ketiga</li><li>N hari ini ditulis</li><li>Saiz ≥ 1 kontrak pada risiko 1%</li><li>Drawdown ≥ 10%? Saiz dikurangkan</li><li>Harga tutup di luar paras 20 hari</li><li>Selari garis tengah 55</li><li>Bukan hari MPOB / hari limit</li><li>Stop 2N bertulis</li><li>Paras exit 10 hari bertulis</li><li>Sanggup rugi tanpa emosi</li></ul><p><small>Rujukan: Siri 2 · slaid 20</small></p>"}, {"n": 17, "k": "Fasa 3 · Pelaksanaan Harian", "t": "Jurnal setiap trade & ukur skor disiplin", "h": "<p>KPI utama bukan untung, tetapi % masa anda ikut SOP 100%. Turtle mengukur prestasi secara objektif — nombor hitam putih, bukan perasaan.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Catat: tarikh, kontrak, N, entry, stop, exit, RM, emosi</li><li>Kira skor disiplin mingguan</li><li>Syarat sebelum live: skor ≥ 95%</li></ul></div><div class=\"nchart\"><img src=\"notes/discipline.webp\" alt=\"Contoh skor disiplin mingguan semasa paper trade.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Contoh skor disiplin mingguan semasa paper trade.</small></p><p><small>Rujukan: Siri 1 · slaid 41 · Siri 2 · slaid 16</small></p>"}, {"n": 18, "k": "Fasa 3 · Pelaksanaan Harian", "t": "Kawal drawdown, bukan kejar untung", "h": "<p>Sistem asas 2026 jatuh hampir RM13,200 dari puncak dengan 3 kerugian berturut-turut. SOP hanya jatuh RM4,800. Drawdown kecil yang membuatkan trader baharu mampu terus ikut sistem.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Jika akaun jatuh 10%, kira saiz guna ekuiti 20% lebih kecil</li><li>Semak drawdown setiap Jumaat</li><li>Jangan tukar sistem semasa drawdown</li></ul></div><div class=\"nchart\"><img src=\"notes/equity.webp\" alt=\"Untung/rugi terkumpul 1 kontrak: Sistem asas vs SOP, 2026.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Untung/rugi terkumpul 1 kontrak: Sistem asas vs SOP, 2026.</small></p><p><small>Rujukan: Siri 1 · slaid 23 · Siri 2 · slaid 19</small></p>"}, {"n": 19, "k": "Fasa 4 · Laluan ke Live", "t": "Backtest dan paper trade sebelum wang sebenar", "h": "<p>Kajian 2026 hanya 6 isyarat — terlalu sedikit untuk bukti. Uji 3–5 tahun data (≥ 30 trade), kemudian paper trade sekurang-kurangnya 60 hari dengan rutin penuh.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Minggu 1: sediakan carta & pelan</li><li>Minggu 2–4: backtest dan kira expectancy</li><li>Hari 28–90: paper trade; live hanya selepas lulus syarat</li></ul></div><div class=\"nchart\"><img src=\"notes/plan.webp\" alt=\"Pelan 120 hari daripada seminar kepada live.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Pelan 120 hari daripada seminar kepada live.</small></p><p><small>Rujukan: Siri 1 · slaid 40 · Siri 2 · slaid 23</small></p>"}, {"n": 20, "k": "Fasa 4 · Laluan ke Live", "t": "Naik saiz berperingkat & terus belajar", "h": "<p>Mulakan live dengan 1 unit sehingga 20 trade. Naik tahap hanya bila nombor membuktikan. Bentuk “suku” 3–5 rakan untuk kongsi jurnal, dan terus membaca — seperti Turtle yang berjaya.</p><div class=\"nc nc-amber\"><h3>Buat sekarang</h3><ul><li>Kekal 1 unit untuk 20 trade live pertama</li><li>Bentuk kumpulan semakan jurnal mingguan</li><li>Baca: Market Wizards, Way of the Turtle, Trend Following</li></ul></div><div class=\"nchart\"><img src=\"notes/ladder.webp\" alt=\"Contoh tangga saiz posisi untuk trader baharu.\" loading=\"lazy\" class=\"nimg\"></div><p><small>Contoh tangga saiz posisi untuk trader baharu.</small></p><p><small>Rujukan: Siri 1 · slaid 34, 40</small></p>"}]};
